def ui(key: str, lang: str, **params) -> str:
    d = UI.get(key, {})
    s = d.get(lang) or d.get("en") or key
    return s.format(**params) if params else s


def drill(name: str, lang: str) -> dict:
    """Display name and instructions for a drill in a language; English is the key."""
    if lang == "en" or name not in DRILLS:
        return {"name": name}
    n, how = DRILLS[name].get(lang, (name, None))
    return {"name": n, "how": how}
